query:
SELECT ?k (COUNT(DISTINCT ?item) AS ?n) WHERE {
  { ?item wdt:P31/wdt:P279* wd:Q48349 . BIND("empires" AS ?k) }
  UNION { VALUES ?root { wd:Q133156 wd:Q164142 wd:Q161243 } ?item wdt:P31/wdt:P279* ?root . BIND("colonies" AS ?k) }
  UNION { ?item wdt:P31/wdt:P279* wd:Q198 . BIND("wars" AS ?k) }
  UNION { ?item wdt:P31/wdt:P279* wd:Q131569 . BIND("treaties_all" AS ?k) }
  UNION { ?item wdt:P31/wdt:P279* wd:Q2401485 . BIND("expeditions" AS ?k) }
  UNION { ?item wdt:P31/wdt:P279* wd:Q10931 . BIND("revolutions" AS ?k) }
  UNION { ?item wdt:P31/wdt:P279* wd:Q11514315 . BIND("eras_all" AS ?k) }
}
GROUP BY ?k
